// Accepts TWO payload shapes so this works without any paid app:
//
// 1. Apple Shortcuts (FREE, the supported path). A flat dictionary of daily
//    metrics, e.g.
//      { "date":"2026-08-27", "steps":8432, "activeEnergy":512,
//        "exerciseMinutes":45, "sleepHours":7.2, "restingHR":58 }
//    Any key may be omitted; only what's present is reported. Values arrive
//    as strings from Shortcuts, so they're coerced.
//
// 2. Health Auto Export's REST API shape ({data:{workouts:[...]}}), kept in
//    case that paid app is ever used. NOTE: workouts are already covered by
//    the Strava integration, so the Shortcuts path deliberately focuses on
//    the daily metrics Strava does NOT provide.
const body = $input.first().json.body || {};

// ---- shape 2: workouts (Health Auto Export) ----
const workouts = (body.data && body.data.workouts) || body.workouts || [];
if (workouts.length) {
  return workouts.map(w => {
    const name = w.name || w.workoutActivityType || 'Workout';
    const start = w.start || w.startDate || '';
    const date = (start || new Date().toISOString()).slice(0, 10);
    const durationMin = w.duration ? Math.round(w.duration / 60) : null;
    const energy = w.totalEnergyBurned && (w.totalEnergyBurned.qty ?? w.totalEnergyBurned);
    const distance = w.totalDistance && (w.totalDistance.qty ?? w.totalDistance);
    const parts = [name];
    if (durationMin) parts.push(`${durationMin} min`);
    if (distance) parts.push(`${distance} ${w.totalDistance?.units || ''}`.trim());
    if (energy) parts.push(`${energy} ${w.totalEnergyBurned?.units || 'kcal'}`.trim());
    return { json: { text: `Apple Health workout: ${parts.join(', ')}`, date } };
  });
}

// ---- shape 1: flat daily metrics (Apple Shortcuts) ----
const num = v => {
  if (v === undefined || v === null || v === '') return null;
  const n = parseFloat(String(v).replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? null : n;
};
const date = (body.date || new Date().toISOString()).slice(0, 10);
const bits = [];
const steps    = num(body.steps);
const energy   = num(body.activeEnergy ?? body.active_energy);
const exercise = num(body.exerciseMinutes ?? body.exercise_minutes);
const sleep    = num(body.sleepHours ?? body.sleep_hours);
const hr       = num(body.restingHR ?? body.resting_hr ?? body.restingHeartRate);
const weight   = num(body.weight);

if (steps    !== null) bits.push(`${Math.round(steps)} steps`);
if (exercise !== null) bits.push(`${Math.round(exercise)} min exercise`);
if (energy   !== null) bits.push(`${Math.round(energy)} kcal active`);
if (sleep    !== null) bits.push(`${sleep.toFixed(1)} h sleep`);
if (hr       !== null) bits.push(`resting HR ${Math.round(hr)}`);
if (weight   !== null) bits.push(`weight ${weight}`);

// Nothing usable - return no items rather than storing an empty record.
if (!bits.length) return [];

return [{ json: { text: `Apple Health daily summary: ${bits.join(', ')}`, date } }];
